def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_d = my.count('D')
    opp_d = opp.count('D')

    last_my = my[-1]
    last_opp = opp[-1]

    if n == 99:
        return 'D'

    recent_opp = opp[-10:] if n >= 10 else opp
    recent_opp_d = recent_opp.count('D')

    if opp_d >= n * 0.5 or recent_opp_d >= 6:
        return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n >= 10 and n % 10 == 0:
                return 'D'
            return 'C'
        else:
            if last_my == 'C' and (my_d + 1) <= n * 0.15:
                return 'D'
            return 'C'
    else:
        if last_opp == 'D':
            if n >= 90:
                return 'D'
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            if recent_opp_d >= 3:
                return 'D'
            if opp_d <= n * 0.15:
                return 'C'
            return 'D'
        else:
            if last_my == 'D':
                return 'C'
            return 'C'
